import uuid

class Queue:
    def __init__(self):
        self._lock = threading.Lock()
        self._jobs = {}
        self._order = []

    def add(self, job_id):
        with self._lock:
            if job_id not in self._jobs:
                self._jobs[job_id] = {'state': 'queued'}
                self._order.append(job_id)

    def claim(self, worker, now, ttl):
        if ttl <= 0:
            return None
        with self._lock:
            for job_id in self._order:
                job = self._jobs[job_id]
                if job['state'] == 'queued' or (job['state'] == 'running' and job['expiry'] <= now):
                    token = str(uuid.uuid4())
                    job.update({
                        'state': 'running',
                        'worker': worker,
                        'token': token,
                        'expiry': now + ttl
                    })
                    return {'job_id': job_id, 'worker': worker, 'token': token}
            return None

    def renew(self, lease, now, ttl):
        with self._lock:
            job_id = lease.get('job_id')
            if job_id not in self._jobs:
                return False
            job = self._jobs[job_id]
            if job.get('state') == 'running' and \
               job.get('worker') == lease.get('worker') and \
               job.get('token') == lease.get('token') and \
               job.get('expiry', float('-inf')) > now:
                job['expiry'] = now + ttl
                return True
            return False

    def complete(self, lease, now):
        with self._lock:
            job_id = lease.get('job_id')
            if job_id not in self._jobs:
                return False
            job = self._jobs[job_id]
            if job.get('state') == 'running' and \
               job.get('worker') == lease.get('worker') and \
               job.get('token') == lease.get('token') and \
               job.get('expiry', float('-inf')) > now:
                job['state'] = 'completed'
                return True
            return False
